UNION ALL SELECT UNISTR('\0622\062E\0631 \0627\062E\062A\0628\0627\0631') AR, 'Last test' EN FROM DUAL
UNION ALL SELECT UNISTR('\0622\062E\0631 \0627\0644\0623\062E\0637\0627\0621') AR, 'Recent errors' EN FROM DUAL
UNION ALL SELECT UNISTR('\0622\062E\0631 \0627\0644\062D\0631\0643\0627\062A \0627\0644\064A\0648\0645') AR, 'Latest punches today' EN FROM DUAL
UNION ALL SELECT UNISTR('\0622\062E\0631 \0628\0635\0645\0629') AR, 'Last punch' EN FROM DUAL
UNION ALL SELECT UNISTR('\0622\062E\0631 \0628\064A\0627\0646\0627\062A \0648\0635\0644\062A \0645\0646 \0627\0644\062C\0647\0627\0632') AR, 'Last data received from device' EN FROM DUAL
UNION ALL SELECT UNISTR('\0622\062E\0631 \062A\062D\062F\064A\062B') AR, 'Updated' EN FROM DUAL
UNION ALL SELECT UNISTR('\0622\062E\0631 \062A\0639\062F\064A\0644') AR, 'Last modified' EN FROM DUAL
UNION ALL SELECT UNISTR('\0622\062E\0631 \062D\0631\0643\0629') AR, 'Last punch' EN FROM DUAL) s ON (t.AR = s.AR)
  WHEN MATCHED THEN UPDATE SET EN = s.EN WHERE t.EN <> s.EN
  WHEN NOT MATCHED THEN INSERT (AR, EN) VALUES (s.AR, s.EN);
  COMMIT;
END;
