UNION ALL SELECT UNISTR('\00AB\0642\0648\0627\0639\062F \0627\0644\062D\0636\0648\0631 \0628\062A\0627\0631\064A\062E\00BB: \0642\0648\0627\0639\062F \0627\0644\062D\0636\0648\0631 \0627\0644\0645\062D\0641\0648\0638\0629 \0647\0646\0627 \062A\064F\0637\0628\0642 \0645\0646 \0627\0644\064A\0648\0645\060C \0648\0644\0627 \064A\062A\063A\064A\0631 \062D\0633\0627\0628 \0627\0644\0623\064A\0627\0645 \0627\0644\0633\0627\0628\0642\0629. \0644\062A\0627\0631\064A\062E \0622\062E\0631 \0623\0648 \0644\0641\062A\0631\0629 \0645\062D\062F\062F\0629: \00AB\0642\0648\0627\0639\062F \0627\062D\062A\0633\0627\0628 \0627\0644\062D\0636\0648\0631 \0628\062A\0627\0631\064A\062E\00BB\060C \0648\0643\0644 \062A\0639\062F\064A\0644 \0628\062A\0627\0631\064A\062E \0641\064A \00AB\0633\062C\0644 \062A\0639\062F\064A\0644\0627\062A \0627\0644\062F\0648\0627\0645 \0648\0627\0644\0642\0648\0627\0639\062F\00BB.') AR, 'Attendance rules from a date: The attendance rules saved here apply from today; the days before are not recalculated. For another date or a set period: Attendance rules by date; every dated change is in Dated changes of hours and rules.' EN FROM DUAL
