UNION ALL SELECT UNISTR('\062D\0633\0627\0628 \0645\0646 \0628\0631\0646\0627\0645\062C \062D\0627\0636\0631 (\0627\0644\0645\0635\062F\0631: \0628\0631\0646\0627\0645\062C \062D\0627\0636\0631) \064A\064F\0639\062F\064E\0651\0644 \0647\0646\0627 \0623\0648 \0641\064A \0627\0644\0628\0631\0646\0627\0645\062C\060C \0648\064A\0635\0644 \0627\0644\062A\0639\062F\064A\0644 \0625\0644\0649 \0627\0644\0628\0631\0646\0627\0645\062C \062E\0644\0627\0644 \062B\0648\0627\0646\064D \0628\0642\0648\0627\0639\062F\0647 \0646\0641\0633\0647\0627: \062D\0633\0627\0628 \0645\062F\064A\0631 \0627\0644\0646\0638\0627\0645 \0644\0627 \064A\0639\062F\0651\0644\0647 \0625\0644\0627 \0645\062F\064A\0631 \0627\0644\0646\0638\0627\0645\060C \0648\0644\0627 \064A\0645\0646\062D \0623\062D\062F \0635\0644\0627\062D\064A\0629 \0644\0627 \064A\0645\0644\0643\0647\0627. \0627\0644\062D\0633\0627\0628 \0627\0644\0645\0631\062A\0628\0637 \0628\0645\0648\0638\0641 \062A\0638\0647\0631 \0644\0647 \00AB\0628\0648\0627\0628\062A\064A\00BB. \062D\0630\0641 \062D\0633\0627\0628 \064A\062D\0630\0641 \062A\0639\064A\064A\0646\0647 \0645\0633\0624\0648\0644\0627\064B \0644\0644\0627\0639\062A\0645\0627\062F.') AR, TO_CHAR(UNISTR('An account from the Hader program (source: the Hader program) is changed here or in the program, and the change reaches the program within seconds under its own rules: only a system administrator changes a system administrator\2019s account, and no one grants a permission they do not have. An account linked to an employee sees \201CMy portal\201D. Deleting an account removes it as an approver.')) EN FROM DUAL
UNION ALL SELECT UNISTR('\062D\0633\0627\0628 \0645\0646 \0646\0638\0627\0645 \0627\0644\062F\0648\0627\0645 (\0627\0644\0645\0635\062F\0631: \0646\0638\0627\0645 \0627\0644\062F\0648\0627\0645) \064A\064F\0639\062F\064E\0651\0644 \0647\0646\0627 \0623\0648 \0641\064A \0627\0644\0628\0631\0646\0627\0645\062C\060C \0648\064A\0635\0644 \0627\0644\062A\0639\062F\064A\0644 \0625\0644\0649 \0627\0644\0628\0631\0646\0627\0645\062C \062E\0644\0627\0644 \062B\0648\0627\0646\064D \0628\0642\0648\0627\0639\062F\0647 \0646\0641\0633\0647\0627: \062D\0633\0627\0628 \0645\062F\064A\0631 \0627\0644\0646\0638\0627\0645 \0644\0627 \064A\0639\062F\0651\0644\0647 \0625\0644\0627 \0645\062F\064A\0631 \0627\0644\0646\0638\0627\0645\060C \0648\0644\0627 \064A\0645\0646\062D \0623\062D\062F \0635\0644\0627\062D\064A\0629 \0644\0627 \064A\0645\0644\0643\0647\0627. \0627\0644\062D\0633\0627\0628 \0627\0644\0645\0631\062A\0628\0637 \0628\0645\0648\0638\0641 \062A\0638\0647\0631 \0644\0647 \00AB\0628\0648\0627\0628\062A\064A\00BB. \062D\0630\0641 \062D\0633\0627\0628 \064A\062D\0630\0641 \062A\0639\064A\064A\0646\0647 \0645\0633\0624\0648\0644\0627\064B \0644\0644\0627\0639\062A\0645\0627\062F.') AR, TO_CHAR(UNISTR('An account from the attendance system (source: the attendance system) is changed here or in the program, and the change reaches the program within seconds under its own rules: only a system administrator changes a system administrator\2019s account, and no one grants a permission they do not have. An account linked to an employee sees \201CMy portal\201D. Deleting an account removes it as an approver.')) EN FROM DUAL
