UNION ALL SELECT UNISTR('\0645\0633\062C\0651\0644') AR, 'Enroller' EN FROM DUAL) s ON (t.AR = s.AR)
  WHEN MATCHED THEN UPDATE SET EN = s.EN WHERE t.EN <> s.EN
