UNION ALL SELECT UNISTR('\0648\0636\0639 \0627\0644\0642\0631\0627\0621\0629 \0641\0642\0637: \0627\0644\062A\0639\062F\064A\0644 \064A\064F\0641\0639\0651\0644 \0639\0646\062F\0645\0627 \064A\0645\0644\0643 \0627\0644\0628\0631\0646\0627\0645\062C \0645\0646\0641\0630 \0627\0644\0623\062C\0647\0632\0629') AR, 'Read-only: changes are enabled when the program owns the terminal port' EN FROM DUAL) s ON (t.AR = s.AR)
