-- ---------------------------------------------------------------- hdr_demo.pks
CREATE OR REPLACE PACKAGE HDR_DEMO AS
  -- A sample company for trying the plug-ins before any terminal is connected: 2 areas, 4 departments,
  -- 36 employees, 5 terminals (one waiting for approval), the punches of the last weeks, leave and a holiday.
  -- While it is loaded the background job keeps it alive: today's punches arrive at their times.
  -- Everything it adds is marked (codes 9001.., DEMO..) and removed by clear. It refuses to mix with real data.
  -- With no Hader server publishing, it also fills the terminals' link tables (HADER_DEV_*: four sample terminals,
  -- areas, people, commands, logs, a beat kept fresh by tick) and answers the pages' terminal requests itself.
  -- p_public Y: the public demo (set_public).
  PROCEDURE load (p_days IN NUMBER DEFAULT 35, p_public IN VARCHAR2 DEFAULT NULL);
  PROCEDURE clear;   -- removes the sample, its link rows, and turns the public demo off
  PROCEDURE tick;   -- called by HDR_JOBS.tick while the sample is loaded
  PROCEDURE english_names;   -- the sample's employees named as this release names them, in Arabic and English
  -- the public demo (HDR_SETTINGS demo.public): Y = every account but the one turning it on (demo.admins) looks and
  -- tries but deletes nothing and changes no system setting, user or key (HDR_UI.visitor / guard); the sample is
  -- loaded again every night (reset, from HDR_JOBS.tick). N = off (the default of every installation).
  PROCEDURE set_public (p_on IN VARCHAR2);
  PROCEDURE reset;
  PROCEDURE terminals;                             -- the sample terminals in HADER_DEV_* (load does it)
  PROCEDURE answer (p_req IN NUMBER DEFAULT NULL); -- the open terminal requests answered: a demo, no terminal
END HDR_DEMO;
/

